     "ts": 1789173551,
     "summary": "【短视频文化现象观察】作者：谭天（中国艺术研究院助理研究员）进入2026年，微短剧已经发展为一个用户规模超7亿、市场规模超千亿的庞大文化产业。面对这样的现象，一个常见的观点是，微短剧的成功主要得益于它能够占据用户的碎片时间，满足受众对情绪价值的需求。这样的说法半对半错。它敏锐地抓住了两个事实：占据时间与提供情绪价值，但又止步于表面化的判断，认为碎片时间意味着现代生活节奏忙碌，情绪价...",
